async function updateEmailLog(logId, status) {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY || !logId) return
  await fetch(`${SUPABASE_URL}/rest/v1/email_logs?id=eq.${logId}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      apikey: SUPABASE_SERVICE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_KEY}`,
    },
    body: JSON.stringify({ status, sent_at: status === 'sent' ? new Date().toISOString() : null }),
  })
}

export const handler = async (event) => {
  const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Content-Type': 'application/json',
  }

  if (event.httpMethod === 'OPTIONS') return { statusCode: 200, headers: corsHeaders, body: '' }
  if (event.httpMethod !== 'POST') return { statusCode: 405, headers: corsHeaders, body: 'Method Not Allowed' }

  if (!RESEND_API_KEY) {
    return { statusCode: 500, headers: corsHeaders, body: JSON.stringify({ error: 'RESEND_API_KEY not configured' }) }
  }

  let body
  try { body = JSON.parse(event.body) }
  catch { return { statusCode: 400, headers: corsHeaders, body: JSON.stringify({ error: 'Invalid JSON' }) } }

  const { full_name, email, id_number, log_id, issued_date } = body

  if (!full_name || !email || !id_number) {
    return { statusCode: 400, headers: corsHeaders, body: JSON.stringify({ error: 'full_name, email, id_number are required' }) }
  }

  try {
    const html = admissionLetterHtml({ full_name, id_number, email, issued_date })

    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${RESEND_API_KEY}`,
      },
      body: JSON.stringify({
        from: `IDEAS-TVET Programme <${FROM_EMAIL}>`,
        to: [email],
        subject: `${id_number} — Your IDEAS-TVET Admission Letter`,
        html,
      }),
    })

    const result = await res.json()
    if (!res.ok) {
      await updateEmailLog(log_id, 'failed')
      return { statusCode: res.status, headers: corsHeaders, body: JSON.stringify({ error: result.message || 'Resend error', detail: result }) }
    }

    await updateEmailLog(log_id, 'sent')
    return { statusCode: 200, headers: corsHeaders, body: JSON.stringify({ success: true, id: result.id }) }

  } catch (err) {
    await updateEmailLog(log_id, 'failed')
    return { statusCode: 500, headers: corsHeaders, body: JSON.stringify({ error: err.message }) }
  }
}
